+    return static_cast<uint32_t>(__dp4a(static_cast<int>(hi), static_cast<int>(0x80C0E0F0u), nib));  // -16..-128
+  }
+
+  // Composite rank key of the bf16 `raw` at row position `pos`: the order-preserving key of the
