+        .row_batch = static_cast<const int32_t*>(row_batch.data_ptr()),
+        .indices_stride = indices.stride(0),
+        .page_table_stride = page_table.stride(0),
+        .num_quads = topk / 4,
+    };
+    const auto grid = dim3{div_ceil(params.num_quads, kBlockSize), num_rows};

