+  template <uint32_t kNumStages>
+  struct Ring {
+    uint32_t stage = 0, phase = 0;
+    SGL_DEVICE void advance(uint32_t step = 1) {
+      stage += step;
+      if (stage >= kNumStages) {
+        stage -= kNumStages;
+        phase ^= 1u;
+      }
