+  // ---- block-scaled MMA (kind::mxf4, UE8M0 scales per 32 elements) --------
+
+  /// e2m1 x e2m1 with A and B from smem (`.block32`); `idesc` from make_instr_desc_mxf4.
+  SGL_DEVICE static void mma_mxf4_ss(
